        if (refs.length !== 1) return null;
        var body = sql.slice(open.end, significant[closeIndex].start).trim();
        var ref = refs[0];
        var hasAlias = ref.next && (isKw(ref.next, 'AS') || (isName(ref.next) && !isKw(ref.next, 'WHERE') && !isKw(ref.next, 'INNER') && !isKw(ref.next, 'LEFT') && !isKw(ref.next, 'RIGHT') && !isKw(ref.next, 'FULL') && !isKw(ref.next, 'CROSS') && !isKw(ref.next, 'JOIN') && !isKw(ref.next, 'ON') && !isKw(ref.next, 'GROUP') && !isKw(ref.next, 'ORDER') && !isKw(ref.next, 'UNION')));
